# Build the transformed grid from the six 5x5 framed objects.
H=W=22
out=[[4]*W for _ in range(H)]
def square(r,c,border,core):
    for dr in range(5):
        for dc in range(5):
            out[r+dr][c+dc] = core if 1<=dr<=3 and 1<=dc<=3 else border
# Border-8 objects slide left; border-2 objects slide right.
for spec in [(3,0,8,6),(12,5,8,7),(16,0,8,2),(5,17,2,1),(9,12,2,9),(17,17,2,6)]:
    square(*spec)
print('\n'.join(' '.join(map(str,row)) for row in out))
